void LoadParticleImages() {
    if (particleImages) return;
    try {
        for(int i=0;i<ParticleCount;++i) TodParticleLoadCompiledDefinition(Particles[i],ParticlePaths[i]);
    } catch (...) {
        for(auto& definition:Particles) TodParticleFreeCompiledDefinition(definition);
        throw;
    }
    particleImages=true;
}
void LoadProjectileImages() {
    if (projectileImages) return;
    DefinitionBindAtlasPath(Projectiles.mTexture, 244, 134, "compiled/atlases/projectiles.atlas.png");
    projectileImages=true;
}
void LoadAllImages() {
    BindFonts();
    for(int i=0;i<ReanimationCount;++i) LoadReanimationImages(i);
    LoadParticleImages();
    LoadProjectileImages();
}
